cases.script:
Create Variable A B Cost Keep;
A = 1;
B = 1;
Cost = 0;
Keep = 41;
Create DifferentialCorrector DC;
DC.ShowProgress = false;
DC.ReportFile = '@OUTPUT@/DC.txt';
Create Yukon Opt;
Opt.ShowProgress = false;
Opt.ReportFile = '@OUTPUT@/Opt.txt';
Opt.FeasibilityTolerance = 1e-9;
Opt.OptimalityTolerance = 1e-9;
Opt.FunctionTolerance = 1e-9;
Create ReportFile Values;
Values.Filename = '@OUTPUT@/values.csv';
Values.WriteHeaders = false;
Values.FixedWidth = false;
Values.Delimiter = ',';
Values.Precision = 17;
BeginMissionSequence;
Target DC {SolveMode = Solve, ExitMode = SaveAndContinue, ShowProgressWindow = false};
Vary DC(A = 1, {Perturbation = 1e-6, Lower = -10, Upper = 10, MaxStep = 10});
Optimize Opt {SolveMode = Solve, ExitMode = SaveAndContinue, ShowProgressWindow = false};
Vary Opt(B = 1, {Perturbation = 1e-6, Lower = -10, Upper = 10, MaxStep = 10});
Cost = (B - 3)^2;
NonlinearConstraint Opt(B >= 4);
Minimize Opt(Cost);
EndOptimize;
Achieve DC(A = 5, {Tolerance = 1e-9});
EndTarget;
Keep = Keep + 1;
Report Values A B Cost Keep;

files.Probe.gmf:
function [answer] = Probe()
Create Variable answer;
Global Trace Counter Message Sat P Control;
BeginMissionSequence;
Toggle Trace Off;
Propagate P(Sat) {Sat.ElapsedSecs = 10};
Counter = Counter + 7;
Toggle Trace On;
Propagate P(Sat) {Sat.ElapsedSecs = 10};
Write Message {Style = Concise};
answer = Counter;

cases.script:
Create Spacecraft Sat;
Sat.DateFormat = A1ModJulian;
Sat.Epoch = '21545';
Sat.CoordinateSystem = EarthMJ2000Eq;
Sat.X = 7000;
Sat.Y = 0;
Sat.Z = 0;
Sat.VX = 0;
Sat.VY = 7.5;
Sat.VZ = 0;
Create ForceModel FM;
FM.PrimaryBodies = {};
FM.PointMasses = {Earth};
FM.Drag = None;
FM.SRP = Off;
Create Propagator P;
P.FM = FM;
P.InitialStepSize = 5;
P.MinStep = 5;
P.MaxStep = 5;
P.Accuracy = 1e-12;
Create Variable Keep Counter Out;
Keep = 41;
Counter = 3;
Out = -1;
Create String Message;
Message = 'COMMAND_FUNCTION_WRITE_WITNESS';
Create ReportFile Values;
Values.Filename = '@OUTPUT@/values.csv';
Values.WriteHeaders = false;
Values.FixedWidth = false;
Values.Delimiter = ',';
Values.Precision = 17;
Create ReportFile Trace Control;
Control.Filename = '@OUTPUT@/control.csv';
Control.WriteHeaders = false;
Control.FixedWidth = false;
Control.Precision = 17;
Control.Add = {Sat.ElapsedSecs};
Trace.Filename = '@OUTPUT@/trace.csv';
Trace.WriteHeaders = false;
Trace.FixedWidth = false;
Trace.Precision = 17;
Trace.Add = {Sat.ElapsedSecs};
Create GmatFunction Probe;
Probe.FunctionPath = '@OUTPUT@/Probe.gmf';
BeginMissionSequence;
Global Trace Counter Message Sat P Control;
[Out] = Probe();
[Out] = Probe();
Keep = Keep + 1;
Report Values Out Counter Keep;

